//! Catalogue of the committed synthetic SnapGene fixtures.
//!
//! Every fixture under `testdata/snapgene/` is generated by this module through
//! `crate::dna_builder`. The catalogue is the single source of truth for the
//! bytes: `tests/snapgene_fixtures.rs` rebuilds each fixture and asserts that
//! the committed file, its sha256 and the entry in `testdata/README.md` all
//! match, and the `gen-snapgene-fixtures` binary writes the files.
//!
//! # Content rules
//!
//! - Every sequence is self-authored and synthetic. No byte of the local
//!   SnapGene corpus is copied, and no file exported by SnapGene is committed
//!   (open question Q8, `testdata/README.md` section 2).
//! - The builder writes no clock, timestamp, filename or random value, so the
//!   catalogue is byte-deterministic.
//! - Fixtures marked "hypothesis" below exist to pin a reader interpretation
//!   of an unverified format fact. They do not confirm that fact; a real
//!   SnapGene file (paired ground truth, `testdata/paired/`) is still required.
//!
//! # What is deliberately absent
//!
//! One plan section 7.3 row cannot be constructed honestly and stays pending
//! in `testdata/README.md`: `133-missing-topology.dna` (no known container
//! construction yields a flags value with no topology signal; O-12). It stays
//! a unit-test trigger.
//!
//! `030-primers.dna` is committed as hypothesis-level coverage only: its
//! non-empty `<Primer>` shape is synthetic because F-17 is unverified. The
//! fixture pins a generic mapping (primer name plus one `Segment` range) and
//! must not be read as a confirmed SnapGene shape.

use crate::dna_builder::{
    lzma_declared_size_bomb, ContainerBuilder, Feature, Notes, Properties, Segment,
    SEQUENCE_TYPE_DNA, SEQUENCE_TYPE_NON_DNA_PLACEHOLDER, SEQUENCE_TYPE_UNKNOWN_PLACEHOLDER,
};

/// 64 bp self-authored "ladder" sequence used by the type-0/type-1 twins.
///
/// It repeats `GATCCTAGAGCTTCGA`, which contains the runs `GATC`, `CTAG`,
/// `AGCT` and `TCGA` so every two-bit value appears in every frame. The
/// twin fixtures let the paired import compare the two encodings of the same
/// molecule.
pub const TWIN_SEQUENCE: &str = "GATCCTAGAGCTTCGAGATCCTAGAGCTTCGAGATCCTAGAGCTTCGAGATCCTAGAGCTTCGA";

/// 138 bp self-authored sequence used by the remaining fixtures.
pub const VECTOR_SEQUENCE: &str =
    "ACGTACGTGGCCTTAAGGCCTTCGAAACGTACGTTAGCATCGATCGTACGATCGATCGTAGCTAGCTAGCATCGATCGTAGCTAGCTAGCATCGATCGTAGCTAGCTAGCGATCGATCGATCGTAGCTAGCTAGCATCGATCGTAGCTAGCTA";

/// Synthetic placeholder history XML. The history payload is validated, never
/// mapped (D14); its content is unverified and deliberately generic.
pub const HISTORY_XML: &str =
    "<?xml version=\"1.0\"?>\n<HistoryTree><Node name=\"sequon-synthetic\"/></HistoryTree>\n";

/// Synthetic placeholder history-modifier XML (type 29). The element shape is
/// unverified (F-21) and the block is never mapped into the model.
pub const HISTORY_MODIFIER_XML: &str = "<?xml version=\"1.0\"?>\n<HistoryModifier><Node \
     name=\"sequon-synthetic\"/></HistoryModifier>\n";

/// Synthetic alignable-sequences XML (type 17). The shape is unverified; the
/// reader preserves the raw payload and does not interpret the alignment.
pub const ALIGNABLE_XML: &str = concat!(
    "<?xml version=\"1.0\"?>\n",
    "<AlignableSequences>\n",
    "  <AlignableSequence name=\"synthetic-alignable\">\n",
    "    <Segment range=\"1-8\"/>\n",
    "  </AlignableSequence>\n",
    "</AlignableSequences>\n",
);

/// Synthetic hypothesis-level non-empty primers XML (F-17 is unverified).
///
/// The shape is invented for fixture coverage and is not a SnapGene fact:
/// the root is the verified `Primers` element, each `Primer` carries a
/// name and its binding site as one `Segment range` (1-based closed, the
/// verified feature convention). Extra attributes (`sequence`, `tm`,
/// `color`) are clearly synthetic. The M4 reader maps it generically and
/// must not derive field semantics from this fixture.
pub const PRIMERS_XML: &str = concat!(
    "<?xml version=\"1.0\"?>\n",
    "<Primers nextValidID=\"2\">\n",
    "  <HybridizationParams minContinuousMatchLen=\"10\" allowMismatch=\"1\" ",
    "minMeltingTemperature=\"40\" showAdditionalFivePrimeMatches=\"1\" ",
    "minimumFivePrimeAnnealing=\"15\"/>\n",
    "  <Primer recentID=\"0\" name=\"M13F\" sequence=\"GTAAAACGACGGCCAGT\" tm=\"58.4\">\n",
    "    <Segment range=\"1-17\" color=\"#ff0000\" type=\"standard\"/>\n",
    "  </Primer>\n",
    "  <Primer recentID=\"1\" name=\"M13R\" sequence=\"CAGGAAACAGCTATGAC\" tm=\"57.1\">\n",
    "    <Segment range=\"30-46\" color=\"#00ff00\" type=\"standard\"/>\n",
    "  </Primer>\n",
    "</Primers>\n",
);

/// One committed fixture definition.
#[derive(Debug, Clone)]
pub struct Fixture {
    /// File name under `testdata/snapgene/`.
    pub name: &'static str,
    /// Exact committed bytes, rebuilt deterministically on every call.
    pub bytes: Vec<u8>,
    /// Expected reader outcome, or "success" with the expected diagnostics.
    pub expected_outcome: &'static str,
    /// Construction caveat: verified fact, builder convention or deferral.
    pub construction: &'static str,
}

/// Returns the documented typed error code for a fixture that must fail, or
/// `None` when the fixture is expected to import.
#[must_use]
pub fn expected_error(name: &str) -> Option<&'static str> {
    Some(match name {
        "070-truncated.dna" => "DNA_TRUNCATED_PACKET",
        "080-lzma-bomb.dna" => "DNA_DECOMPRESSION_LIMIT",
        "090-deep-xml.dna" => "DNA_XML_DEPTH_EXCEEDED",
        "110-both-dna-packets.dna" => "DNA_DUPLICATE_DNA_PACKET",
        "120-no-dna-packet.dna" => "DNA_NO_DNA_PACKET",
        "130-missing-name.dna" => "RECORD_REQUIRED_FIELD_MISSING",
        "131-rna-seq-type.dna" => "DNA_UNKNOWN_SEQ_TYPE",
        "132-unknown-seq-type.dna" => "DNA_UNKNOWN_SEQ_TYPE",
        _ => return None,
    })
}

/// Returns the informational diagnostic codes a successful fixture must
/// report. A clean fixture returns an empty slice; the gate additionally
/// requires that no error-severity diagnostic appears.
#[must_use]
pub fn expected_diagnostics(name: &str) -> &'static [&'static str] {
    match name {
        "005-unknown-flag-bits.dna" => &["DNA_TOPOLOGY_FLAG_UNKNOWN"],
        "010-history-v14.dna" | "011-history-v17.dna" | "064-history-modifier.dna" => {
            &["DNA_HISTORY_PRESERVED_RAW"]
        }
        "050-traces.dna"
        | "061-restriction-sites.dna"
        | "062-enzyme-settings.dna"
        | "063-alignable-sequences.dna" => &["DNA_PACKET_IGNORED"],
        "060-unknown-packet.dna" => &["DNA_UNKNOWN_PACKET"],
        "100-unicode-notes.dna" => &["DNA_SEQUENCE_NORMALIZED"],
        _ => &[],
    }
}

/// Returns the successful fixtures, which are the ones with a committed
/// canonical JSON golden.
#[must_use]
pub fn successful() -> Vec<Fixture> {
    all()
        .into_iter()
        .filter(|fixture| expected_error(fixture.name).is_none())
        .collect()
}

/// Returns the fixtures that must fail with a documented typed error.
#[must_use]
pub fn failing() -> Vec<Fixture> {
    all()
        .into_iter()
        .filter(|fixture| expected_error(fixture.name).is_some())
        .collect()
}

/// Returns every committed fixture, in file-name order.
#[must_use]
pub fn all() -> Vec<Fixture> {
    let mut fixtures = matrix_fixtures();
    fixtures.extend(additive_fixtures());
    fixtures.extend(diagnostic_and_container_fixtures());
    fixtures.sort_by(|left, right| left.name.cmp(right.name));
    fixtures
}

/// Notes block that supplies a record name through `CustomMapLabel`.
fn named_notes(name: &str) -> Notes {
    let mut notes = Notes::new();
    notes.field("UUID", "00000000-0000-4000-8000-000000000001");
    notes.field("Type", "Synthetic");
    notes.field("ConfirmedExperimentally", "0");
    notes.field("CustomMapLabel", name);
    notes.field("UseCustomMapLabel", "1");
    notes.field("Organism", "synthetic construct");
    notes
}

/// Notes block with no usable name source, for the missing-name fixture.
fn nameless_notes() -> Notes {
    let mut notes = Notes::new();
    notes.field("UUID", "00000000-0000-4000-8000-000000000002");
    notes.field("Type", "Synthetic");
    notes.field("UseCustomMapLabel", "0");
    notes.field("Comments", "");
    notes
}

/// Simple linear feature list used by fixtures that are not about features.
fn minimal_features() -> Vec<Feature> {
    vec![Feature::new("misc_feature", vec![Segment::new(1, 8)]).name("synthetic site")]
}

/// Plan section 7.3 fixtures that the verified container layout can construct.
fn matrix_fixtures() -> Vec<Fixture> {
    let mut fixtures = Vec::new();

    // 001: type 0, linear flags, minimal features. (F-5, F-6 zero case, F-12)
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, TWIN_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-001"))
        .push_features(&minimal_features());
    fixtures.push(Fixture {
        name: "001-linear-uncompressed.dna",
        bytes: container.build(),
        expected_outcome: "success; topology linear; sequence equals source",
        construction: "verified container and type 0 layout; flags bit 0 zero case",
    });

    // 002: type 1 2-bit, circular, same molecule as 001. (F-8 to F-11 hypothesis)
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna_2bit(0x01, TWIN_SEQUENCE)
        .expect("2-bit fixture uses GATC bases")
        .push_notes(&named_notes("sequon-fixture-002"));
    fixtures.push(Fixture {
        name: "002-circular-compressed.dna",
        bytes: container.build(),
        expected_outcome: "success; topology circular; sequence equals 001",
        construction: "builder convention (2-bit layout unverified, F-8 to F-11)",
    });

    // 004: explicit all-zero flags. (F-6 zero case)
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-004"));
    fixtures.push(Fixture {
        name: "004-linear-zero-flags.dna",
        bytes: container.build(),
        expected_outcome: "success; topology linear",
        construction: "verified layout; flags byte 0x00",
    });

    // 010: export_version 14, plain XML history. (F-20)
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 14);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-010"))
        .push_history_xml(HISTORY_XML);
    fixtures.push(Fixture {
        name: "010-history-v14.dna",
        bytes: container.build(),
        expected_outcome: "success; history preserved; DNA_HISTORY_PRESERVED_RAW (info)",
        construction: "builder convention: plain XML below export 15 (F-20)",
    });

    // 011: export_version 17, LZMA history. (F-20)
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 17);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-011"))
        .push_history_xml(HISTORY_XML);
    fixtures.push(Fixture {
        name: "011-history-v17.dna",
        bytes: container.build(),
        expected_outcome: "success; history preserved; DNA_HISTORY_PRESERVED_RAW (info)",
        construction: "builder convention: LZMA-alone at or above export 15 (F-20)",
    });

    // 012: export_version 15 with no history packet. (C-5, F-29)
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-012"));
    fixtures.push(Fixture {
        name: "012-version15-no-history.dna",
        bytes: container.build(),
        expected_outcome: "success; no history diagnostic or preservation entry",
        construction: "verified: version 15 does not imply a history packet",
    });

    // 013: packets deliberately out of type order (F-25).
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_notes(&named_notes("sequon-fixture-013"))
        .push_dna(0x00, VECTOR_SEQUENCE);
    let mut properties = Properties::new();
    properties.field("UpstreamStickiness", "0");
    container.push_properties(&properties);
    fixtures.push(Fixture {
        name: "013-unsorted-packets.dna",
        bytes: container.build(),
        expected_outcome: "success; packet order 6, 0, 8 preserved",
        construction: "verified: packet order is not sorted (F-25)",
    });

    // 020: multi-segment feature with join order preserved. (F-13 hypothesis)
    let feature = Feature::new(
        "misc_feature",
        vec![Segment::new(20, 30), Segment::new(5, 10)],
    )
    .name("join-order")
    .directionality(2);
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x01, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-020"))
        .push_features(&[feature]);
    fixtures.push(Fixture {
        name: "020-features-multisegment.dna",
        bytes: container.build(),
        expected_outcome: "success; operator join; segment order preserved; strand -1",
        construction: "hypothesis: multi-segment Feature/Segment shape (F-13 branch)",
    });

    // 021: feature/segment attributes, Q text/int/HTML, directionality variants.
    let features = vec![
        Feature::new(
            "CDS",
            vec![Segment::new(4, 12)
                .attribute("color", "#cc99b2")
                .attribute("type", "standard")
                .attribute("translated", "1")],
        )
        .name("attr")
        .directionality(2)
        .attribute("allowSegmentOverlaps", "0")
        .int_qualifier("codon_start", 1)
        .text_qualifier("product", "synthetic beta-lactamase")
        .text_qualifier("note", "<html><body><i>lac</i> & more</body></html>"),
        Feature::new(
            "misc_feature",
            vec![Segment::new(1, 3).attribute("color", "#99ccff")],
        )
        .text_qualifier("note", "plain text value"),
        Feature::new(
            "promoter",
            vec![Segment::new(30, 40).attribute("type", "standard")],
        )
        .directionality(1)
        .text_qualifier("note", "forward promoter"),
    ];
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x01, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-021"))
        .push_features(&features);
    fixtures.push(Fixture {
        name: "021-features-attributes.dna",
        bytes: container.build(),
        expected_outcome: "success; Q text/int/HTML values, attributes and strands preserved",
        construction: "verified XML shape; multi-segment branch not used",
    });

    // 030: non-empty primers, hypothesis-level shape (F-17 unverified).
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-030"))
        .push_primers_raw(PRIMERS_XML);
    fixtures.push(Fixture {
        name: "030-primers.dna",
        bytes: container.build(),
        expected_outcome: "success; primer name plus Segment range mapped generically",
        construction: "hypothesis: synthetic Primer shape, F-17 unverified",
    });

    // 031: empty Primers document with HybridizationParams (F-30).
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-031"))
        .push_empty_primers();
    fixtures.push(Fixture {
        name: "031-primers-empty-settings.dna",
        bytes: container.build(),
        expected_outcome: "success; extras.snapgene.primers empty; settings preserved",
        construction: "verified empty Primers root; non-empty shape deliberately absent (F-17)",
    });

    // 040: notes and properties extras, HTML description.
    let mut notes = named_notes("sequon-fixture-040");
    notes.field(
        "Description",
        "<html><body>synthetic vector description</body></html>",
    );
    notes.field("CreatedBy", "Sequon conformance builder");
    notes.field_with_attributes("Created", "2026.1.1", &[("UTC", "0:0:0")]);
    notes.field("Comments", "<html><body></body></html>");
    let mut properties = Properties::new();
    properties.field("UpstreamStickiness", "0");
    properties.field("DownstreamStickiness", "0");
    properties.field("UpstreamModification", "FivePrimePhosphorylated");
    properties.field("DownstreamModification", "FivePrimePhosphorylated");
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&notes)
        .push_properties(&properties);
    fixtures.push(Fixture {
        name: "040-notes-properties.dna",
        bytes: container.build(),
        expected_outcome: "success; notes/properties in extras.snapgene",
        construction: "verified Notes and AdditionalSequenceProperties shape (F-18, F-19)",
    });

    // 041: name from CustomMapLabel with UseCustomMapLabel=1.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-custom-label"));
    fixtures.push(Fixture {
        name: "041-name-custom-map-label.dna",
        bytes: container.build(),
        expected_outcome: "success; name from CustomMapLabel",
        construction: "verified name precedence branch (F-18)",
    });

    // 042: name precedence and description fallback.
    let mut notes = Notes::new();
    notes.field("AccessionNumber", "SYN0001");
    notes.field("Type", "Synthetic");
    notes.field("CustomMapLabel", "ignored-label");
    notes.field("UseCustomMapLabel", "0");
    notes.field(
        "Description",
        "<html><body>preferred description</body></html>",
    );
    notes.field("Comments", "plain comments text");
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container.push_dna(0x00, VECTOR_SEQUENCE).push_notes(&notes);
    fixtures.push(Fixture {
        name: "042-name-precedence.dna",
        bytes: container.build(),
        expected_outcome: "success; name AccessionNumber; description from Description",
        construction: "verified field names; AccessionNumber branch not in corpus (F-18)",
    });

    fixtures
}

/// Calibration-derived fixtures proposed by the design note section 11.1 that
/// are not already represented by a plan section 7.3 file.
fn additive_fixtures() -> Vec<Fixture> {
    let mut fixtures = Vec::new();

    // 003: the corpus-observed flag byte 0x1f, circular, name from notes.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x1f, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-003"));
    fixtures.push(Fixture {
        name: "003-type0-observed-flags.dna",
        bytes: container.build(),
        expected_outcome: "success; circular; name from CustomMapLabel; no flag warning",
        construction: "verified flags value 0x1f (bits 0-4 are the known-normal mask)",
    });

    // 005: bit 5 outside the observed mask is reported but does not fail.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x21, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-005"));
    fixtures.push(Fixture {
        name: "005-unknown-flag-bits.dna",
        bytes: container.build(),
        expected_outcome: "success; circular; DNA_TOPOLOGY_FLAG_UNKNOWN (info)",
        construction: "mask policy is a calibration assumption (F-7)",
    });

    // 061: type 3 restriction-site framing.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-061"))
        .push_restriction_sites(
            &["GAATTC", "GGATCC", "CTCGAG", "AAGCTT"],
            &[0x00, 0x01, 0x02, 0x03],
        );
    fixtures.push(Fixture {
        name: "061-restriction-sites.dna",
        bytes: container.build(),
        expected_outcome: "success; DNA_PACKET_IGNORED (info); payload preserved",
        construction: "verified type 3 framing; opaque tail is synthetic (F-26)",
    });

    // 062: type 13 enzyme-settings framing.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-062"))
        .push_enzyme_settings("Unique 6+ Cutters");
    fixtures.push(Fixture {
        name: "062-enzyme-settings.dna",
        bytes: container.build(),
        expected_outcome: "success; DNA_PACKET_IGNORED (info); payload preserved",
        construction: "observed label and header positions; field semantics unverified (F-27)",
    });

    // 063: type 17 alignable sequences, preserved and not interpreted.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-063"))
        .push_alignable_raw(ALIGNABLE_XML);
    fixtures.push(Fixture {
        name: "063-alignable-sequences.dna",
        bytes: container.build(),
        expected_outcome: "success; DNA_PACKET_IGNORED (info); payload preserved",
        construction: "hypothesis: type 17 XML shape unverified; reader preserves raw bytes",
    });

    // 064: type 29 history modifier, version rule assumed to match type 7.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 17);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-064"))
        .push_history_modifier_xml(HISTORY_MODIFIER_XML);
    fixtures.push(Fixture {
        name: "064-history-modifier.dna",
        bytes: container.build(),
        expected_outcome: "success; DNA_HISTORY_PRESERVED_RAW (info); raw payload preserved",
        construction: "hypothesis: type 29 follows the type-7 version rule (F-21); synthetic XML",
    });

    fixtures
}

/// Renders deeply nested features XML for the depth-limit fixture.
///
/// The nesting uses unknown elements inside a known block, which the reader
/// still counts toward `max_xml_depth`.
fn deep_features_xml(depth: usize) -> String {
    let mut xml = String::from(
        "<?xml version=\"1.0\"?>\n<Features nextValidID=\"1\">\n  <Feature recentID=\"0\" \
         name=\"deep\" type=\"misc_feature\">\n    <Segment range=\"1-8\"/>\n",
    );
    for _ in 0..depth {
        xml.push_str("<N>");
    }
    xml.push('x');
    for _ in 0..depth {
        xml.push_str("</N>");
    }
    xml.push_str("\n  </Feature>\n</Features>\n");
    xml
}

/// Plan section 7.3 rows that this builder can construct but that are not in
/// the calibration subset above.
fn diagnostic_and_container_fixtures() -> Vec<Fixture> {
    let mut fixtures = Vec::new();

    // 050: a small opaque trace container, within the preservation budget.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-050"))
        .push_trace("sequon-synthetic-trace-payload");
    fixtures.push(Fixture {
        name: "050-traces.dna",
        bytes: container.build(),
        expected_outcome: "success; DNA_PACKET_IGNORED (info); payload preserved",
        construction: "opaque payload: trace internals are not interpreted in v1 (F-22)",
    });

    // 060: a packet type the reader cannot know.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-060"))
        .push_raw(42, b"sequon-unknown-packet".to_vec());
    fixtures.push(Fixture {
        name: "060-unknown-packet.dna",
        bytes: container.build(),
        expected_outcome: "success; DNA_UNKNOWN_PACKET (info); payload preserved",
        construction: "unknown type 42 is synthetic and has no format meaning",
    });

    // 070: declared packet length reaches past the end of the file.
    let mut valid = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    valid
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-070"));
    let valid_bytes = valid.build();
    fixtures.push(Fixture {
        name: "070-truncated.dna",
        bytes: valid.build_truncated(valid_bytes.len() - 10),
        expected_outcome: "error DNA_TRUNCATED_PACKET",
        construction: "verified TLV framing; the file is cut inside the last packet",
    });

    // 080: LZMA-alone header declares an unpacked size above the output cap.
    //
    // A ratio-only bomb is not constructible with lzma-rs 0.3.0: its encoder
    // reaches about 40:1 on repeated input, below the 200:1 ratio cap. The
    // declared-size pre-check in design section 2.8 is the constructible
    // variant of the same limit, and the reader must reject it before it
    // decodes or allocates.
    let bomb = lzma_declared_size_bomb(64 * 1024 * 1024 + 1);
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-080"))
        .push_history_raw(bomb);
    fixtures.push(Fixture {
        name: "080-lzma-bomb.dna",
        bytes: container.build(),
        expected_outcome: "error DNA_DECOMPRESSION_LIMIT from the declared-size header check",
        construction:
            "hypothesis: LZMA-alone header declares 64 MiB + 1 unpacked bytes (F-20); no OOM",
    });

    // 090: XML nested beyond max_xml_depth.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-090"))
        .push_raw(10, deep_features_xml(80).into_bytes());
    fixtures.push(Fixture {
        name: "090-deep-xml.dna",
        bytes: container.build(),
        expected_outcome: "error DNA_XML_DEPTH_EXCEEDED",
        construction: "verified XML framing; unknown nested elements exercise the depth cap",
    });

    // 100: lowercase type 0 bases and UTF-8 notes.
    let mut notes = Notes::new();
    notes.field("UUID", "00000000-0000-4000-8000-000000000100");
    notes.field("Type", "Synthetic");
    notes.field("CustomMapLabel", "sequon-fixture-100");
    notes.field("UseCustomMapLabel", "1");
    notes.field("Description", "Synthetic naïve construct - café");
    notes.field("Organism", "Escherichia coli synthetic");
    notes.field("Comments", "UTF-8: naïve café — synthetic data");
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, &TWIN_SEQUENCE.to_ascii_lowercase())
        .push_notes(&notes);
    fixtures.push(Fixture {
        name: "100-unicode-notes.dna",
        bytes: container.build(),
        expected_outcome: "success; DNA_SEQUENCE_NORMALIZED (info); notes text preserved",
        construction: "verified layout; lowercase bases exercise normalisation (F-12 branch)",
    });

    // 110: two DNA packets in one container.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, TWIN_SEQUENCE)
        .push_dna_2bit(0x01, TWIN_SEQUENCE)
        .expect("2-bit fixture uses GATC bases")
        .push_notes(&named_notes("sequon-fixture-110"));
    fixtures.push(Fixture {
        name: "110-both-dna-packets.dna",
        bytes: container.build(),
        expected_outcome: "error DNA_DUPLICATE_DNA_PACKET",
        construction: "verified type 0 plus builder-convention type 1",
    });

    // 120: metadata only, no DNA packet.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container.push_notes(&named_notes("sequon-fixture-120"));
    let mut properties = Properties::new();
    properties.field("UpstreamStickiness", "0");
    container.push_properties(&properties);
    fixtures.push(Fixture {
        name: "120-no-dna-packet.dna",
        bytes: container.build(),
        expected_outcome: "error DNA_NO_DNA_PACKET",
        construction: "verified metadata packets only",
    });

    // 130: no usable name source and no hint.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_DNA, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&nameless_notes());
    fixtures.push(Fixture {
        name: "130-missing-name.dna",
        bytes: container.build(),
        expected_outcome: "error RECORD_REQUIRED_FIELD_MISSING { field: name }",
        construction: "verified notes shape; no name source is present",
    });

    // 131: non-1 sequence type; strict lead decision maps it to unknown.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_NON_DNA_PLACEHOLDER, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-131"));
    fixtures.push(Fixture {
        name: "131-rna-seq-type.dna",
        bytes: container.build(),
        expected_outcome: "error DNA_UNKNOWN_SEQ_TYPE",
        construction: "strict lead decision: only sequence type 1 is DNA; 2 is an unknown value, not verified RNA (F-4)",
    });

    // 132: sequence type outside the observed enum.
    let mut container = ContainerBuilder::new(SEQUENCE_TYPE_UNKNOWN_PLACEHOLDER, 15);
    container
        .push_dna(0x00, VECTOR_SEQUENCE)
        .push_notes(&named_notes("sequon-fixture-132"));
    fixtures.push(Fixture {
        name: "132-unknown-seq-type.dna",
        bytes: container.build(),
        expected_outcome: "error DNA_UNKNOWN_SEQ_TYPE",
        construction: "builder convention: sequence type 0 is outside the enum (F-4)",
    });

    fixtures
}
